@import '@fontsource/barlow-condensed/400.css';
@import '@fontsource/barlow-condensed/500.css';
@import '@fontsource/barlow-condensed/600.css';
@import '@fontsource/barlow-condensed/700.css';
@import '@fontsource/ibm-plex-mono/400.css';
@import '@fontsource/ibm-plex-mono/500.css';
@import '@fontsource/ibm-plex-mono/600.css';

:root {
  --font-display: 'Barlow Condensed', 'Arial Narrow', 'Liberation Sans Narrow', sans-serif;
  --font-mono: 'IBM Plex Mono', 'Consolas', monospace;
  --font-body: 'Barlow Condensed', 'Segoe UI', sans-serif;
  --accent: #d3b77b;
  --accent-soft: rgba(211, 183, 123, 0.16);
  --accent-line: rgba(211, 183, 123, 0.34);
  --ink: #e9e5d7;
  --ink-dim: #b7b4a4;
  --ink-faint: #858477;
  --panel: rgba(17, 20, 15, 0.88);
  --panel-solid: #14170f;
  --panel-2: rgba(28, 31, 23, 0.82);
  --line: rgba(235, 230, 210, 0.14);
  --line-strong: rgba(235, 230, 210, 0.26);
  --danger: #e0705a;
  --good: #8fd3a6;
  --player: #7ad9c5;
  --enemy: #e0705a;
  --faction: #d3b77b;
  --shadow: 0 24px 70px rgba(0, 0, 0, 0.5);
}
body[data-era='ww2'] {
  --accent: #dfbf84;
  --accent-soft: rgba(223, 191, 132, 0.16);
  --accent-line: rgba(223, 191, 132, 0.34);
  --panel: rgba(18, 19, 14, 0.89);
}
body[data-era='modern'] {
  --accent: #79dcc7;
  --accent-soft: rgba(121, 220, 199, 0.14);
  --accent-line: rgba(121, 220, 199, 0.32);
  --panel: rgba(13, 19, 18, 0.9);
  --player: #79dcc7;
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; height: 100%; overflow: hidden; background: #0d100c; }
body {
  font-family: var(--font-body);
  color: var(--ink);
  font-size: 15px;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overscroll-behavior: none;
}
button { font-family: inherit; color: inherit; background: none; border: 0; cursor: pointer; }
button:focus-visible { outline: 1px solid var(--accent); outline-offset: 3px; }
small, em, kbd { font-family: var(--font-mono); font-style: normal; }
.hidden { display: none !important; }
#app, #viewport { position: fixed; inset: 0; }
#viewport { background: #10140f; }
#viewport canvas { display: block; touch-action: none; }
#viewport canvas.placing { cursor: crosshair; }
.screen-grain, .screen-scan { position: fixed; inset: 0; pointer-events: none; z-index: 60; }
.screen-grain {
  opacity: 0.05;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.55'/%3E%3C/svg%3E");
  mix-blend-mode: overlay;
}
.screen-scan {
  opacity: 0.4;
  background: repeating-linear-gradient(180deg, rgba(0, 0, 0, 0.11) 0px, rgba(0, 0, 0, 0.11) 1px, transparent 1px, transparent 3px);
  mix-blend-mode: multiply;
}

/* ──────────────────────────── loading ──────────────────────────── */
.loading {
  position: fixed; inset: 0; z-index: 200; background: #0b0e0a;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 16px;
  transition: opacity 0.6s ease;
}
.loading.out { opacity: 0; pointer-events: none; }
.loading-emblem {
  width: 76px; height: 76px; border: 1px solid var(--accent-line); display: grid; place-items: center;
  font-family: var(--font-display); font-weight: 700; font-size: 28px; color: var(--accent);
  letter-spacing: 0.12em; transform: rotate(45deg); background: rgba(0,0,0,0.25);
}
.loading-emblem::first-line { transform: rotate(-45deg); }
.loading-title { font-family: var(--font-display); font-size: 38px; letter-spacing: 0.34em; font-weight: 600; }
.loading-bar { width: min(320px, 70vw); height: 2px; background: rgba(255,255,255,0.12); overflow: hidden; }
.loading-bar span { display: block; height: 100%; width: 20%; background: var(--accent); transition: width 0.35s ease; }
.loading-text { font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.22em; color: var(--ink-faint); }
.fatal {
  position: fixed; inset: 0; z-index: 300; background: #0c0e0a; display: grid; place-items: center; padding: 30px;
  font-family: var(--font-mono); font-size: 13px; color: #e6b3a5; text-align: center; white-space: pre-wrap;
}

/* ──────────────────────────── menu ──────────────────────────── */
.menu {
  position: fixed; inset: 0; z-index: 40; display: flex; flex-direction: column;
  padding: 26px clamp(20px, 3.2vw, 52px) 14px;
  overflow: hidden;
}
.menu-gradient {
  position: absolute; inset: 0; pointer-events: none; z-index: -1;
  background:
    linear-gradient(90deg, rgba(8, 11, 7, 0.94) 0%, rgba(8, 11, 7, 0.78) 32%, rgba(8, 11, 7, 0.2) 66%, rgba(8, 11, 7, 0.04) 100%),
    linear-gradient(0deg, rgba(8, 11, 7, 0.9) 0%, transparent 27%, transparent 78%, rgba(8, 11, 7, 0.65) 100%);
}
.menu-header { display: flex; justify-content: space-between; align-items: flex-start; flex: 0 0 auto; }
.brand-kicker {
  display: flex; align-items: center; gap: 10px;
  font-family: var(--font-mono); font-size: 9px; letter-spacing: 0.3em; color: var(--accent); opacity: 0.9;
}
.brand-kicker span { display: block; width: 26px; height: 1px; background: var(--accent-line); }
.brand-title {
  margin: 5px 0 2px; display: flex; flex-direction: column; line-height: 0.76;
  font-family: var(--font-display); font-weight: 700; letter-spacing: -0.02em; text-transform: uppercase;
}
.brand-iron { font-size: clamp(68px, 8.2vw, 118px); color: var(--ink); }
.brand-epochs {
  font-size: clamp(68px, 8.2vw, 118px);
  color: transparent; -webkit-text-stroke: 1px var(--accent);
  margin-left: clamp(18px, 3vw, 50px);
  position: relative;
}
.brand-epochs::before {
  content: ''; position: absolute; left: -18px; top: 56%; width: 10px; height: 10px;
  background: var(--accent); transform: translateY(-50%) rotate(45deg);
}
.brand-sub { font-family: var(--font-mono); font-size: 9px; letter-spacing: 0.32em; color: var(--ink-dim); margin-top: 12px; }
.menu-header-right { display: flex; align-items: center; gap: 12px; padding-top: 10px; }
.live-chip {
  display: flex; align-items: center; gap: 8px; padding: 7px 12px;
  font-family: var(--font-mono); font-size: 9px; letter-spacing: 0.18em; color: var(--ink-dim);
  border: 1px solid var(--line); background: rgba(0,0,0,0.22);
}
.live-chip i { width: 6px; height: 6px; border-radius: 50%; background: var(--good); box-shadow: 0 0 10px var(--good); animation: pulse-dot 2.4s infinite; }
@keyframes pulse-dot { 0%,100% { opacity: 1 } 50% { opacity: 0.3 } }
.ghost-btn {
  padding: 8px 13px; border: 1px solid var(--line); background: rgba(0,0,0,0.24);
  font-family: var(--font-mono); font-size: 9px; letter-spacing: 0.16em; color: var(--ink-dim);
  transition: border-color 0.2s, color 0.2s, background 0.2s;
}
.ghost-btn:hover { border-color: var(--accent-line); color: var(--accent); background: var(--accent-soft); }

.menu-body {
  flex: 1 1 auto; min-height: 0; display: grid;
  grid-template-columns: minmax(250px, 0.95fr) minmax(280px, 1.2fr) minmax(290px, 1fr);
  gap: clamp(16px, 2.4vw, 36px); align-items: start;
  padding: clamp(14px, 2.3vh, 30px) 0 8px;
  overflow-y: auto; scrollbar-width: thin; scrollbar-color: var(--accent-line) transparent;
}
.menu-col { display: flex; flex-direction: column; min-width: 0; }
.panel-label {
  display: flex; align-items: center; gap: 10px; margin-bottom: 11px;
  font-family: var(--font-mono); font-size: 9px; letter-spacing: 0.24em; color: var(--ink-faint);
}
.panel-label b { font-weight: 500; color: var(--accent); }
.panel-label .line { flex: 1; height: 1px; background: linear-gradient(90deg, var(--line), transparent); }

/* era cards */
.era-list { display: flex; flex-direction: column; gap: 8px; }
.era-card {
  position: relative; display: grid; grid-template-columns: 54px 1fr auto; gap: 13px; align-items: center;
  text-align: left; padding: 12px 14px 12px 12px; border: 1px solid var(--line);
  background: linear-gradient(100deg, rgba(12, 15, 10, 0.72), rgba(12, 15, 10, 0.4));
  transition: border-color 0.22s ease, background 0.22s ease, transform 0.22s ease;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 9px), calc(100% - 9px) 100%, 0 100%);
}
.era-card::before { content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 2px; background: transparent; transition: background 0.2s; }
.era-card:hover { border-color: var(--line-strong); background: rgba(20, 24, 16, 0.72); transform: translateX(2px); }
.era-card.active { border-color: var(--accent-line); background: linear-gradient(100deg, var(--accent-soft), rgba(12, 15, 10, 0.55)); }
.era-card.active::before { background: var(--accent); }
.era-numeral {
  width: 46px; height: 54px; display: grid; place-items: center;
  font-family: var(--font-display); font-weight: 600; font-size: 34px; color: var(--ink-faint);
  border-right: 1px solid var(--line); transition: color 0.2s;
}
.era-card.active .era-numeral, .era-card:hover .era-numeral { color: var(--accent); }
.era-name { font-family: var(--font-display); font-size: 22px; font-weight: 600; letter-spacing: 0.03em; line-height: 1.05; text-transform: uppercase; }
.era-years { font-family: var(--font-mono); font-size: 8.5px; color: var(--accent); letter-spacing: 0.16em; margin-top: 4px; }
.era-tag { font-size: 11px; color: var(--ink-faint); margin-top: 4px; line-height: 1.25; max-width: 240px; }
.era-count { display: flex; flex-direction: column; align-items: flex-end; gap: 3px; font-family: var(--font-mono); font-size: 8px; color: var(--ink-faint); letter-spacing: 0.08em; }
.era-count b { font-size: 14px; color: var(--ink-dim); font-weight: 500; }
.menu-note {
  margin-top: 14px; padding: 12px 14px; border-left: 1px solid var(--accent-line);
  background: linear-gradient(90deg, rgba(0,0,0,0.18), transparent);
  font-size: 12px; line-height: 1.45; color: var(--ink-faint); min-height: 58px;
}

/* map cards */
.map-list { display: flex; flex-direction: column; gap: 8px; }
.map-card {
  display: grid; grid-template-columns: 104px 1fr; gap: 13px; align-items: stretch; text-align: left;
  padding: 7px; border: 1px solid var(--line); background: rgba(12, 15, 10, 0.58);
  transition: border-color 0.2s, background 0.2s, transform 0.2s;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%);
}
.map-card:hover { border-color: var(--line-strong); background: rgba(20, 24, 16, 0.7); transform: translateX(2px); }
.map-card.active { border-color: var(--accent-line); background: linear-gradient(90deg, var(--accent-soft), rgba(12,15,10,0.55)); }
.map-thumb { position: relative; overflow: hidden; min-height: 66px; border: 1px solid rgba(255,255,255,0.09); }
.map-thumb canvas { width: 100%; height: 100%; display: block; object-fit: cover; }
.map-thumb::after { content: ''; position: absolute; inset: 0; background: linear-gradient(0deg, rgba(0,0,0,0.55), transparent 55%), repeating-linear-gradient(90deg, rgba(255,255,255,0.035) 0 1px, transparent 1px 4px); }
.map-scan { position: absolute; left: 6px; top: 6px; z-index: 2; font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.14em; color: rgba(255,255,255,0.75); background: rgba(0,0,0,0.45); padding: 2px 4px; }
.map-info { display: flex; flex-direction: column; justify-content: center; min-width: 0; padding-right: 4px; }
.map-name { font-family: var(--font-display); font-size: 20px; font-weight: 600; letter-spacing: 0.03em; text-transform: uppercase; line-height: 1; }
.map-region { font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.14em; color: var(--accent); margin-top: 4px; }
.map-tags { display: flex; gap: 5px; margin-top: 7px; flex-wrap: wrap; }
.map-tags span { font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.1em; color: var(--ink-faint); border: 1px solid var(--line); padding: 2px 5px; }
.map-brief { margin-top: 13px; padding: 12px 14px; border: 1px solid var(--line); border-left: 1px solid var(--accent-line); background: rgba(0,0,0,0.26); min-height: 86px; }
.map-brief-kicker { font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.22em; color: var(--accent); }
.map-brief p { margin: 7px 0 0; font-size: 12px; line-height: 1.45; color: var(--ink-dim); }

/* factions */
.faction-list { display: flex; flex-direction: column; gap: 7px; }
.faction-card {
  display: grid; grid-template-columns: 42px 1fr auto; gap: 11px; align-items: center; text-align: left;
  padding: 8px 11px; border: 1px solid var(--line); background: rgba(12, 15, 10, 0.58);
  transition: border-color 0.2s, background 0.2s, transform 0.2s;
}
.faction-card:hover { border-color: var(--line-strong); background: rgba(20, 24, 16, 0.7); transform: translateX(2px); }
.faction-card.active { border-color: var(--fc, var(--accent)); background: linear-gradient(90deg, rgba(255,255,255,0.05), rgba(12,15,10,0.55)); }
.faction-emblem {
  width: 40px; height: 40px; display: grid; place-items: center; font-family: var(--font-display);
  font-weight: 700; font-size: 16px; letter-spacing: 0.02em; color: #12150f;
  background: var(--fc, var(--accent)); position: relative;
  clip-path: polygon(50% 0, 100% 22%, 100% 78%, 50% 100%, 0 78%, 0 22%);
}
.faction-emblem::after { content: ''; position: absolute; inset: 4px; border: 1px solid rgba(0,0,0,0.3); clip-path: inherit; }
.faction-meta { min-width: 0; }
.faction-name { font-family: var(--font-display); font-size: 18px; font-weight: 600; letter-spacing: 0.03em; text-transform: uppercase; line-height: 1; }
.faction-doctrine { font-family: var(--font-mono); font-size: 7.5px; letter-spacing: 0.12em; color: var(--fc, var(--accent)); margin-top: 4px; text-transform: uppercase; }
.faction-blurb { font-size: 10.5px; color: var(--ink-faint); line-height: 1.3; margin-top: 4px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.faction-bars { display: flex; flex-direction: column; gap: 3px; width: 44px; }
.faction-bars span { height: 3px; background: rgba(255,255,255,0.09); position: relative; overflow: hidden; }
.faction-bars span::after { content: ''; position: absolute; inset: 0; transform-origin: left; background: var(--fc, var(--accent)); transform: scaleX(var(--v, 0.6)); }

.matchup-card {
  display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 8px;
  margin-top: 12px; padding: 10px 12px; border: 1px solid var(--line); background: rgba(0,0,0,0.28);
}
.matchup-side { min-width: 0; }
.matchup-side-right { text-align: right; }
.matchup-label { display: block; font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.15em; color: var(--ink-faint); }
.matchup-side strong { display: block; font-family: var(--font-display); font-size: 14px; letter-spacing: 0.03em; margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.matchup-side small { display: block; font-family: var(--font-mono); font-size: 7px; color: var(--ink-faint); margin-top: 2px; }
.matchup-vs { font-family: var(--font-display); font-size: 14px; color: var(--accent); border: 1px solid var(--accent-line); width: 28px; height: 28px; display: grid; place-items: center; transform: rotate(45deg); }
.matchup-vs::first-line { transform: rotate(-45deg); }
.roster-count { display: grid; grid-template-columns: repeat(4, 1fr); gap: 5px; margin-top: 8px; }
.roster-count div { border: 1px solid var(--line); padding: 5px 2px 4px; text-align: center; background: rgba(0,0,0,0.18); }
.roster-count b { display: block; font-family: var(--font-display); font-size: 19px; line-height: 1; color: var(--accent); font-weight: 500; }
.roster-count span { font-family: var(--font-mono); font-size: 6px; letter-spacing: 0.1em; color: var(--ink-faint); }
.start-btn {
  position: relative; width: 100%; margin-top: 10px; padding: 13px 18px 12px;
  display: flex; align-items: baseline; gap: 10px; text-align: left;
  background: var(--accent); color: #11150e;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%);
  transition: filter 0.2s, transform 0.15s;
  box-shadow: 0 12px 40px rgba(0,0,0,0.35);
}
.start-btn:hover { filter: brightness(1.12); transform: translateY(-1px); }
.start-btn:active { transform: translateY(0); }
.start-label { font-family: var(--font-display); font-size: 30px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; line-height: 1; }
.start-meta { margin-left: auto; font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.12em; opacity: 0.72; }
.start-arrow { font-size: 24px; line-height: 1; }
.start-btn.small { width: auto; margin-top: 0; padding: 12px 22px; }
.start-btn.small .start-label { font-size: 22px; }
.start-note { margin-top: 7px; font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.08em; color: var(--ink-faint); text-align: center; }
.menu-footer {
  flex: 0 0 auto; display: flex; justify-content: space-between; align-items: center; gap: 20px;
  border-top: 1px solid var(--line); padding-top: 10px;
}
.footer-controls { display: flex; gap: 16px; flex-wrap: wrap; }
.footer-controls span { font-family: var(--font-mono); font-size: 7.5px; letter-spacing: 0.1em; color: var(--ink-faint); display: flex; align-items: center; gap: 5px; }
.footer-controls kbd { border: 1px solid var(--line-strong); padding: 2px 5px; color: var(--ink-dim); font-size: 7px; }
.footer-credit { font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.16em; color: var(--ink-faint); text-align: right; }

/* ──────────────────────────── in-game HUD ──────────────────────────── */
.game-ui { position: fixed; inset: 0; z-index: 30; pointer-events: none; }
.game-ui > * { pointer-events: auto; }
.hud-top {
  position: absolute; top: 0; left: 0; right: 0; height: 58px;
  display: flex; align-items: center; gap: 18px; padding: 0 14px;
  background: linear-gradient(180deg, rgba(9, 12, 8, 0.96), rgba(9, 12, 8, 0.76) 70%, transparent);
  border-bottom: 1px solid var(--accent-line);
  backdrop-filter: blur(10px);
}
.hud-top::after { content: ''; position: absolute; left: 0; bottom: -1px; width: 180px; height: 1px; background: var(--accent); box-shadow: 0 0 14px var(--accent); }
.hud-brand { display: flex; align-items: center; gap: 9px; padding-right: 16px; border-right: 1px solid var(--line); height: 36px; }
.hud-brand-mark {
  width: 34px; height: 34px; display: grid; place-items: center; border: 1px solid var(--accent-line);
  color: var(--accent); font-family: var(--font-display); font-size: 18px; font-weight: 600; transform: rotate(45deg);
  background: rgba(0,0,0,0.25);
}
.hud-brand-mark::first-line { transform: rotate(-45deg); }
.hud-brand-text b { display: block; font-family: var(--font-display); font-size: 16px; letter-spacing: 0.16em; line-height: 1; }
.hud-brand-text small { display: block; font-size: 6.5px; letter-spacing: 0.14em; color: var(--ink-faint); margin-top: 3px; }
.hud-faction { display: flex; align-items: center; gap: 9px; min-width: 0; }
.hud-emblem {
  width: 30px; height: 30px; display: grid; place-items: center; clip-path: polygon(50% 0, 100% 22%, 100% 78%, 50% 100%, 0 78%, 0 22%);
  background: var(--faction); color: #11150e; font-family: var(--font-display); font-weight: 700; font-size: 11px;
}
.hud-faction b { display: block; font-family: var(--font-display); font-size: 15px; letter-spacing: 0.04em; line-height: 1; white-space: nowrap; }
.hud-faction small { display: block; font-size: 6.5px; color: var(--ink-faint); letter-spacing: 0.08em; margin-top: 3px; white-space: nowrap; }
.hud-resources { display: flex; align-items: center; gap: 6px; margin-left: auto; }
.res-chip { display: flex; align-items: center; gap: 8px; padding: 5px 10px; border: 1px solid var(--line); background: rgba(0,0,0,0.28); height: 38px; min-width: 104px; }
.res-chip span small { display: block; font-size: 6px; letter-spacing: 0.14em; color: var(--ink-faint); }
.res-chip b { display: block; font-family: var(--font-mono); font-size: 13px; font-weight: 500; color: var(--ink); letter-spacing: 0.02em; line-height: 1.1; }
.res-chip em { margin-left: auto; font-family: var(--font-mono); font-size: 8px; color: var(--good); }
.res-icon { width: 17px; height: 17px; display: grid; place-items: center; font-size: 13px; color: var(--accent); border: 1px solid var(--accent-line); }
.pop-icon { color: var(--player); border-color: rgba(121, 217, 197, 0.3); font-size: 9px; }
.obj-chip { min-width: 210px; }
.obj-icon { font-size: 12px; }
.obj-chip b { font-family: var(--font-display); font-size: 11px; letter-spacing: 0.08em; color: var(--ink-dim); }
.obj-chip em { color: var(--enemy); font-size: 10px; }
.hud-clock { text-align: right; padding-left: 12px; border-left: 1px solid var(--line); }
.hud-clock small { display: block; font-size: 6px; letter-spacing: 0.18em; color: var(--ink-faint); }
.hud-clock b { font-family: var(--font-mono); font-size: 14px; font-weight: 500; color: var(--accent); }
.hud-menu-btn { height: 32px; padding: 0 12px; border: 1px solid var(--line); font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.16em; color: var(--ink-dim); }
.hud-menu-btn:hover { border-color: var(--accent-line); color: var(--accent); }

.capture-strip {
  position: absolute; top: 68px; left: 50%; transform: translateX(-50%);
  display: flex; gap: 6px; z-index: 2;
}
.cap-chip {
  display: flex; align-items: center; gap: 6px; padding: 4px 9px;
  font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.08em;
  border: 1px solid var(--line); background: rgba(8, 11, 7, 0.7); color: var(--ink-faint);
  transition: all 0.2s;
}
.cap-chip i { width: 6px; height: 6px; border-radius: 50%; background: var(--ink-faint); box-shadow: 0 0 6px currentColor; }
.cap-chip.player { border-color: rgba(121,217,197,0.35); color: var(--player); }
.cap-chip.player i { background: var(--player); }
.cap-chip.enemy { border-color: rgba(224,112,90,0.35); color: var(--enemy); }
.cap-chip.enemy i { background: var(--enemy); }
.cap-chip.contested { border-color: rgba(211,183,123,0.45); color: var(--accent); }
.cap-chip.contested i { background: var(--accent); animation: pulse-dot 1s infinite; }
.cap-chip b { color: var(--ink); font-weight: 500; }

/* war table */
.war-table {
  position: absolute; top: 70px; right: 12px; bottom: 92px; width: 342px;
  display: flex; flex-direction: column; background: var(--panel); border: 1px solid var(--line);
  box-shadow: var(--shadow); backdrop-filter: blur(16px);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%);
}
.wt-head { display: flex; justify-content: space-between; align-items: flex-start; padding: 13px 14px 9px; border-bottom: 1px solid var(--line); }
.wt-kicker { font-family: var(--font-mono); font-size: 6.5px; letter-spacing: 0.22em; color: var(--accent); }
.wt-title { font-family: var(--font-display); font-size: 22px; font-weight: 600; letter-spacing: 0.1em; line-height: 1; margin-top: 3px; }
.icon-btn { width: 26px; height: 26px; display: grid; place-items: center; border: 1px solid var(--line); color: var(--ink-faint); font-size: 10px; }
.icon-btn:hover { border-color: var(--accent-line); color: var(--accent); }
.wt-close { display: none; }
.wt-tabs { display: grid; grid-template-columns: repeat(3, 1fr); border-bottom: 1px solid var(--line); }
.wt-tab {
  padding: 8px 4px; font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.16em; color: var(--ink-faint);
  border-right: 1px solid var(--line); border-bottom: 2px solid transparent; transition: all 0.18s;
}
.wt-tab:last-child { border-right: 0; }
.wt-tab:hover { color: var(--ink); background: rgba(255,255,255,0.03); }
.wt-tab.active { color: var(--accent); border-bottom-color: var(--accent); background: var(--accent-soft); }
.wt-content { flex: 1; overflow-y: auto; padding: 10px; scrollbar-width: thin; scrollbar-color: var(--accent-line) transparent; }
.wt-footer { padding: 7px 12px; border-top: 1px solid var(--line); font-family: var(--font-mono); font-size: 6.5px; letter-spacing: 0.06em; color: var(--ink-faint); line-height: 1.4; }

.panel-section-label { display: flex; justify-content: space-between; align-items: center; font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.16em; color: var(--ink-faint); margin: 8px 2px 6px; }
.panel-section-label:first-child { margin-top: 0; }
.panel-section-label b { color: var(--accent); font-weight: 500; }
.build-card {
  display: grid; grid-template-columns: 44px 1fr auto; gap: 9px; align-items: center; width: 100%;
  text-align: left; padding: 8px; margin-bottom: 5px; border: 1px solid var(--line);
  background: rgba(255,255,255,0.018); transition: all 0.18s;
}
.build-card:hover { border-color: var(--accent-line); background: var(--accent-soft); }
.build-card.disabled { opacity: 0.4; }
.build-card.locked { opacity: 0.6; }
.bc-icon, .unit-icon {
  width: 42px; height: 42px; display: grid; place-items: center; border: 1px solid var(--line);
  background: radial-gradient(circle at 40% 30%, rgba(255,255,255,0.06), rgba(0,0,0,0.3)); color: var(--accent);
}
.bc-icon svg, .unit-icon svg, .sel-icon svg { width: 25px; height: 25px; }
.bc-name { font-family: var(--font-display); font-size: 15px; letter-spacing: 0.03em; text-transform: uppercase; line-height: 1; }
.bc-desc { font-size: 9.5px; color: var(--ink-faint); line-height: 1.25; margin-top: 3px; }
.bc-cost { text-align: right; font-family: var(--font-mono); font-size: 8px; color: var(--ink-dim); }
.bc-cost b { display: block; font-size: 12px; color: var(--accent); font-weight: 500; }
.bc-cost small { display: block; color: var(--ink-faint); font-size: 6.5px; margin-top: 2px; }
.unit-row {
  display: grid; grid-template-columns: 34px 1fr auto auto; gap: 7px; align-items: center;
  width: 100%; text-align: left; padding: 5px 6px; border: 1px solid transparent; border-bottom-color: var(--line);
  transition: all 0.16s;
}
.unit-row:hover { background: rgba(255,255,255,0.04); border-color: var(--accent-line); }
.unit-row.disabled { opacity: 0.42; }
.unit-row .unit-icon { width: 32px; height: 32px; border: 0; background: rgba(0,0,0,0.24); }
.unit-row .unit-icon svg { width: 20px; height: 20px; }
.ur-name { font-family: var(--font-display); font-size: 14px; letter-spacing: 0.02em; line-height: 1; }
.ur-meta { font-family: var(--font-mono); font-size: 6.5px; color: var(--ink-faint); margin-top: 3px; }
.ur-stats { display: flex; gap: 6px; font-family: var(--font-mono); font-size: 6px; color: var(--ink-faint); margin-top: 2px; }
.ur-cost { font-family: var(--font-mono); font-size: 10px; color: var(--accent); text-align: right; }
.ur-cost small { display: block; font-size: 6px; color: var(--ink-faint); }
.queue-badge {
  display: inline-grid; place-items: center; min-width: 17px; height: 17px; padding: 0 3px;
  background: var(--accent); color: #11150e; font-family: var(--font-mono); font-size: 8px; font-weight: 600;
  margin-left: 4px;
}
.unit-row.queueable { border-left: 2px solid var(--accent); }
.req-line { font-family: var(--font-mono); font-size: 6.5px; color: var(--danger); margin-top: 2px; }
.intel-block { padding: 10px; border: 1px solid var(--line); margin-bottom: 8px; background: rgba(0,0,0,0.18); }
.intel-block h4 { margin: 0 0 6px; font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.2em; color: var(--accent); font-weight: 500; }
.intel-block p { margin: 0; font-size: 11.5px; line-height: 1.45; color: var(--ink-dim); }
.intel-block .intel-big { font-family: var(--font-display); font-size: 20px; letter-spacing: 0.03em; color: var(--ink); text-transform: uppercase; line-height: 1; margin-bottom: 5px; }
.intel-kv { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; margin-top: 8px; }
.intel-kv div { border: 1px solid var(--line); padding: 5px 7px; }
.intel-kv small { display: block; font-size: 6px; letter-spacing: 0.12em; color: var(--ink-faint); }
.intel-kv b { display: block; font-family: var(--font-mono); font-size: 11px; color: var(--ink); font-weight: 500; margin-top: 2px; }
.intel-controls { display: grid; grid-template-columns: 1fr; gap: 4px; font-size: 10.5px; color: var(--ink-dim); }
.intel-controls div { display: flex; justify-content: space-between; gap: 8px; border-bottom: 1px dashed rgba(255,255,255,0.06); padding: 3px 0; }
.intel-controls kbd { border: 1px solid var(--line); padding: 1px 4px; font-size: 7px; color: var(--ink-faint); }

/* selection card */
.selection-card {
  position: absolute; left: 14px; bottom: 96px; width: 318px;
  background: var(--panel); border: 1px solid var(--line); box-shadow: var(--shadow);
  padding: 10px; backdrop-filter: blur(14px);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%);
}
.sel-top { display: grid; grid-template-columns: 48px 1fr auto; gap: 9px; align-items: start; }
.sel-icon { width: 46px; height: 46px; display: grid; place-items: center; border: 1px solid var(--accent-line); color: var(--accent); background: rgba(0,0,0,0.25); }
.sel-kicker { font-family: var(--font-mono); font-size: 6.5px; letter-spacing: 0.16em; color: var(--accent); }
.sel-title b { display: block; font-family: var(--font-display); font-size: 18px; letter-spacing: 0.03em; line-height: 1.05; text-transform: uppercase; }
.sel-title small { display: block; font-size: 6.5px; color: var(--ink-faint); margin-top: 3px; letter-spacing: 0.04em; }
.sel-hp { height: 3px; background: rgba(255,255,255,0.1); margin: 8px 0 7px; position: relative; overflow: hidden; }
.sel-hp span { position: absolute; inset: 0; transform-origin: left; background: var(--player); transition: transform 0.2s; }
.sel-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 4px; }
.sel-stat { border: 1px solid var(--line); padding: 4px 5px; background: rgba(0,0,0,0.18); }
.sel-stat small { display: block; font-size: 5.5px; letter-spacing: 0.1em; color: var(--ink-faint); }
.sel-stat b { font-family: var(--font-mono); font-size: 9.5px; font-weight: 500; color: var(--ink-dim); }
.sel-actions { display: flex; gap: 5px; margin-top: 7px; flex-wrap: wrap; }
.sel-action {
  flex: 1; min-width: 66px; padding: 5px 8px; border: 1px solid var(--line);
  font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.1em; color: var(--ink-dim);
  transition: all 0.18s;
}
.sel-action:hover { border-color: var(--accent-line); color: var(--accent); background: var(--accent-soft); }
.sel-action.primary { background: var(--accent); border-color: var(--accent); color: #11150e; }
.sel-queue { display: grid; gap: 3px; margin-top: 6px; }
.queue-item { display: grid; grid-template-columns: 1fr auto; gap: 6px; font-family: var(--font-mono); font-size: 7px; color: var(--ink-dim); border-top: 1px dashed var(--line); padding-top: 3px; }
.queue-item span:last-child { color: var(--accent); }

/* minimap */
.minimap-wrap {
  position: absolute; left: 14px; bottom: 12px; width: 250px;
  background: var(--panel); border: 1px solid var(--line); padding: 6px;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%);
  backdrop-filter: blur(10px);
}
.minimap-head { display: flex; justify-content: space-between; align-items: center; padding: 1px 2px 5px; }
.minimap-head span { font-family: var(--font-mono); font-size: 6.5px; letter-spacing: 0.18em; color: var(--ink-faint); }
.mini-btn { font-family: var(--font-mono); font-size: 6px; letter-spacing: 0.08em; color: var(--accent); border: 1px solid var(--accent-line); padding: 2px 5px; }
.mini-btn:hover { background: var(--accent-soft); }
#minimap { display: block; width: 100%; height: auto; background: #131810; border: 1px solid rgba(255,255,255,0.08); cursor: crosshair; touch-action: none; }
.minimap-legend { display: flex; gap: 9px; padding-top: 5px; }
.minimap-legend span { font-family: var(--font-mono); font-size: 5.5px; letter-spacing: 0.06em; color: var(--ink-faint); display: flex; align-items: center; gap: 4px; }
.minimap-legend i { width: 5px; height: 5px; display: block; border-radius: 50%; }
.lg-player { background: var(--player); }
.lg-enemy { background: var(--enemy); }
.lg-cap { background: var(--accent); }

/* command dock */
.command-dock {
  position: absolute; left: 50%; bottom: 12px; transform: translateX(-50%);
  display: flex; align-items: center; gap: 7px; padding: 6px 8px;
  background: var(--panel); border: 1px solid var(--line); backdrop-filter: blur(12px);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 9px), calc(100% - 9px) 100%, 0 100%);
}
.cmd-group { display: flex; gap: 4px; }
.cmd-divider { width: 1px; height: 36px; background: var(--line); }
.cmd-btn {
  position: relative; width: 56px; height: 46px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px;
  border: 1px solid var(--line); background: rgba(255,255,255,0.018); transition: all 0.16s;
}
.cmd-btn:hover { border-color: var(--accent-line); background: var(--accent-soft); }
.cmd-btn.active { border-color: var(--accent); background: var(--accent-soft); }
.cmd-btn:disabled { opacity: 0.35; cursor: not-allowed; }
.cmd-glyph { font-size: 16px; line-height: 1; color: var(--accent); }
.cmd-btn small { font-family: var(--font-mono); font-size: 5.5px; letter-spacing: 0.1em; color: var(--ink-faint); }
.ability-btn { border-color: var(--accent-line); }
.cooldown-ring { position: absolute; inset: 0; background: rgba(0,0,0,0.7); transform-origin: bottom; pointer-events: none; opacity: 0; }
.ability-btn.cooling .cooldown-ring { opacity: 1; }
.cmd-hint {
  max-width: 180px; padding: 0 8px; font-family: var(--font-mono); font-size: 6px; letter-spacing: 0.04em;
  color: var(--ink-faint); line-height: 1.5;
}

/* notifications */
.notif-stack { position: absolute; top: 72px; left: 50%; transform: translateX(-50%); display: flex; flex-direction: column; gap: 4px; align-items: center; pointer-events: none; z-index: 6; }
.notif {
  display: flex; align-items: center; gap: 8px; padding: 5px 12px;
  background: rgba(9, 12, 8, 0.88); border: 1px solid var(--line); border-left: 2px solid var(--accent);
  font-family: var(--font-mono); font-size: 7.5px; letter-spacing: 0.06em; color: var(--ink-dim);
  animation: notif-in 0.25s ease both;
}
.notif.warn { border-left-color: var(--danger); color: #e9b3a6; }
.notif.good { border-left-color: var(--good); }
.notif.out { animation: notif-out 0.35s ease both; }
@keyframes notif-in { from { opacity: 0; transform: translateY(-5px); } }
@keyframes notif-out { to { opacity: 0; transform: translateY(-8px); } }

/* placement / misc */
.placement-banner {
  position: absolute; top: 96px; left: 50%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 14px; padding: 7px 12px;
  background: rgba(9, 12, 8, 0.9); border: 1px solid var(--accent-line);
  font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.12em; color: var(--accent);
}
.placement-hint { color: var(--ink-faint); font-size: 6.5px; }
.placement-banner.invalid { border-color: var(--danger); color: var(--danger); }
.lock-banner { position: absolute; top: 50%; left: 50%; transform: translate(-50%,-50%); padding: 20px 30px; background: rgba(9,12,8,0.92); border: 1px solid var(--danger); font-family: var(--font-mono); color: var(--danger); font-size: 11px; letter-spacing: 0.15em; }
.cursor-tip { position: fixed; z-index: 100; padding: 5px 8px; background: rgba(8,10,7,0.94); border: 1px solid var(--accent-line); font-family: var(--font-mono); font-size: 7px; color: var(--ink); pointer-events: none; transform: translate(14px, 14px); white-space: nowrap; }
.select-box { position: fixed; z-index: 50; border: 1px solid var(--accent); background: rgba(121, 217, 197, 0.11); pointer-events: none; box-shadow: inset 0 0 0 1px rgba(255,255,255,0.1); }
.mobile-table-toggle { display: none; position: absolute; right: 10px; bottom: 76px; padding: 8px 12px; background: var(--panel); border: 1px solid var(--accent-line); font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.1em; color: var(--accent); z-index: 7; }
.mobile-ability { display: none; }

/* end screen */
.end-screen { position: fixed; inset: 0; z-index: 80; display: grid; place-items: center; background: rgba(5,7,4,0.72); backdrop-filter: blur(7px); }
.end-card { width: min(560px, 90vw); padding: 28px 30px; background: var(--panel-solid); border: 1px solid var(--accent-line); box-shadow: var(--shadow); position: relative; clip-path: polygon(0 0, 100% 0, 100% calc(100% - 20px), calc(100% - 20px) 100%, 0 100%); }
.end-card::before { content: ''; position: absolute; left: 0; top: 0; width: 120px; height: 2px; background: var(--accent); }
.end-kicker { font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.24em; color: var(--accent); }
.end-card h2 { margin: 7px 0 8px; font-family: var(--font-display); font-size: clamp(52px, 8vw, 86px); line-height: 0.85; letter-spacing: 0.03em; }
.end-screen.lose h2 { color: var(--enemy); }
.end-card p { margin: 0; font-size: 13px; color: var(--ink-dim); line-height: 1.5; max-width: 430px; }
.end-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; margin: 18px 0; }
.end-stats div { border: 1px solid var(--line); padding: 8px; }
.end-stats small { display: block; font-size: 6px; letter-spacing: 0.12em; color: var(--ink-faint); }
.end-stats b { display: block; font-family: var(--font-display); font-size: 22px; font-weight: 500; color: var(--accent); }
.end-actions { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }

/* overlay canvas for health bars */
#hud-overlay { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; z-index: 2; }

