  .start-btn { position: sticky; bottom: 0; margin-top: 8px; padding: 11px 14px; z-index: 3; }
  .start-label { font-size: 26px; }
  .start-note { display: none; }
  .menu-footer { flex-direction: column; align-items: flex-start; gap: 6px; padding-top: 8px; margin-top: 12px; }
  .footer-credit { text-align: left; font-size: 6px; }
  .footer-controls { gap: 8px; }
  .footer-controls span { font-size: 6px; }
  .footer-controls kbd { display: none; }

  .hud-top { height: 50px; gap: 7px; padding: 0 8px; }
  .hud-brand-mark { width: 28px; height: 28px; font-size: 14px; }
  .hud-faction b { font-size: 12px; }
  .hud-emblem { width: 24px; height: 24px; font-size: 9px; }
  .hud-resources { gap: 3px; }
  .res-chip { min-width: 0; padding: 3px 6px; height: 32px; gap: 5px; }
  .res-chip span small { font-size: 5px; }
  .res-chip b { font-size: 10px; }
  .res-chip em { font-size: 6px; }
  .res-icon { width: 14px; height: 14px; font-size: 10px; }
  .pop-icon { display: none; }
  .res-chip:nth-child(2) { display: none; }
  .hud-menu-btn { height: 28px; padding: 0 7px; font-size: 6px; }
  .capture-strip { top: 56px; gap: 3px; }
  .cap-chip { padding: 2px 5px; font-size: 5.5px; }
  .cap-chip b { display: none; }

  .war-table {
    top: 54px; right: 8px; bottom: 72px; width: min(340px, calc(100vw - 16px));
    transform: translateX(calc(100% + 20px)); transition: transform 0.28s cubic-bezier(0.2,0.8,0.2,1);
    z-index: 20;
  }
  .war-table.open { transform: translateX(0); }
  .wt-close { display: grid; }
  .mobile-table-toggle { display: block; }
  .selection-card { left: 8px; right: 8px; bottom: 72px; width: auto; max-width: none; z-index: 8; }
  .selection-card .sel-stats { grid-template-columns: repeat(4, 1fr); }
  .command-dock { left: 8px; right: 8px; bottom: 8px; transform: none; justify-content: space-around; padding: 4px; gap: 3px; }
  .cmd-group { gap: 3px; }
  .cmd-divider { display: none; }
  .cmd-btn { width: 42px; height: 38px; }
  .cmd-glyph { font-size: 13px; }
  .cmd-btn small { font-size: 5px; }
  .cmd-hint { display: none; }
  #minimap-wrap, .minimap-wrap { left: 8px; bottom: 68px; width: 116px; padding: 4px; z-index: 5; }
  .minimap-head span { font-size: 5px; }
  .minimap-head .mini-btn { display: none; }
  .minimap-legend { display: none; }
  .game-ui:has(.selection-card:not(.hidden)) .minimap-wrap { display: none; }
  .mobile-table-toggle { bottom: 68px; padding: 6px 9px; font-size: 6.5px; }
  .notif-stack { top: 58px; max-width: 90vw; }
  .notif { font-size: 6.5px; padding: 4px 8px; }
  .placement-banner { top: 80px; gap: 8px; font-size: 7px; padding: 5px 8px; }
  .placement-hint { display: none; }
  .end-card { padding: 22px 18px; }
  .end-stats { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 420px) {
  .hud-faction { display: none; }
  .hud-menu-btn { margin-left: auto; }
  .cmd-btn { width: 38px; height: 36px; }
  .start-meta { display: none; }
  .brand-sub { display: none; }
  .matchup-side strong { font-size: 12px; }
