    const color = this.type === 'snow' ? 0xf0f5f7 : this.type === 'dust' ? 0xd6bd8e : 0xb7c7c7
    const size = this.type === 'snow' ? 0.48 : this.type === 'dust' ? 0.34 : 0.16
    this.material = new THREE.PointsMaterial({
