import * as THREE from 'three'
import { createMuzzleFlash, createWreck } from './models.js'
import { clamp, entityCenter, entityRadius } from './util.js'

const _center = new THREE.Vector3()
const _pos = new THREE.Vector3()

export function installCombat(proto) {
  Object.assign(proto, {
    // ── target acquisition ────────────────────────────────────────────────
    findEnemyNear(source, radius, includeAir = false) {
      let best = null
      let bestDistance = radius
      for (const unit of this.units) {
        if (unit.dead || unit.team === source.team) continue
        if (unit.aircraft && !includeAir) continue
        const distance = Math.hypot(unit.x - source.x, unit.z - source.z)
        if (distance < bestDistance) {
          best = unit
          bestDistance = distance
        }
      }
      for (const building of this.buildings) {
        if (building.dead || building.team === source.team) continue
        if (!building.built) continue
        const distance = Math.hypot(building.x - source.x, building.z - source.z)
        if (distance < bestDistance) {
          best = building
          bestDistance = distance
        }
      }
      return best
    },

    // ── projectile creation ───────────────────────────────────────────────
    fireBullet(attacker, target, muzzle) {
      const targetPoint = entityCenter(target, new THREE.Vector3())
      targetPoint.x += (Math.random() - 0.5) * 0.4
      targetPoint.y += (Math.random() - 0.5) * 0.4
      targetPoint.z += (Math.random() - 0.5) * 0.4
      const distance = muzzle.distanceTo(targetPoint)
      const mesh = new THREE.Mesh(
        new THREE.SphereGeometry(0.16, 5, 4),
        new THREE.MeshBasicMaterial({ color: 0xffd58a, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false }),
      )
      mesh.position.copy(muzzle)
      this.scene.add(mesh)
      this.projectiles.push({
        kind: 'bullet',
        mesh,
        start: muzzle.clone(),
        end: targetPoint,
        t: 0,
        duration: clamp(distance / 260, 0.06, 0.34),
        arc: 0.25 + distance * 0.005,
        trail: false,
        target,
        source: attacker,
        damage: attacker.def.damage,
        splash: 0,
        crater: 0,
      })
      this.sfx.shoot('bullet')
    },

    fireShell(attacker, target, muzzle) {
      const kind = attacker.def.projectile || 'shell'
      const targetPoint = entityCenter(target, new THREE.Vector3())
      const groundY = this.terrain.sample(targetPoint.x, targetPoint.z)
      const end = new THREE.Vector3(targetPoint.x, Math.max(groundY + 0.5, targetPoint.y - 0.4), targetPoint.z)
      const distance = muzzle.distanceTo(end)
      const mesh = new THREE.Mesh(
        new THREE.SphereGeometry(kind === 'bomb' ? 0.55 : 0.3, 6, 5),
        new THREE.MeshBasicMaterial({ color: kind === 'bomb' ? 0x3a3a33 : 0xffc477, depthWrite: false }),
      )
      mesh.position.copy(muzzle)
      this.scene.add(mesh)
      const splash = attacker.def.splash || (kind === 'bomb' ? 9 : 3.2)
      this.projectiles.push({
        kind,
        mesh,
        start: muzzle.clone(),
        end,
        t: 0,
        duration: clamp(0.35 + distance / 125, 0.35, 2.15),
        arc: kind === 'bomb' ? 3.5 : 8 + distance * 0.05,
        trail: true,
        target,
        source: attacker,
        damage: attacker.def.damage,
        splash,
        crater: attacker.def.crater || 0,
      })
      this.sfx.shoot(kind === 'bomb' ? 'bomb' : 'shell')
    },

    spawnArtilleryRound(strike) {
      const x = strike.x
      const z = strike.z
      const ground = this.terrain.sample(x, z)
      const mesh = new THREE.Mesh(
        new THREE.SphereGeometry(0.55, 6, 5),
        new THREE.MeshBasicMaterial({ color: 0xffd58a, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false }),
      )
      const start = new THREE.Vector3(x - 6 - Math.random() * 4, ground + 125, z - 5 - Math.random() * 4)
      mesh.position.copy(start)
      this.scene.add(mesh)
      this.projectiles.push({
        kind: 'artillery',
        mesh,
        start,
        end: new THREE.Vector3(x, ground + 0.4, z),
        t: 0,
        duration: 0.48,
        arc: 0,
        trail: true,
        source: strike.source || { team: 'player', dead: false, def: { damage: strike.damage } },
        damage: strike.damage || 180,
        splash: strike.splash || 16,
        crater: strike.crater || 8,
        artillery: true,
      })
      this.sfx.shoot('shell')
    },

    // ── impacts ───────────────────────────────────────────────────────────
    impact(projectile) {
      const point = projectile.end
      if (projectile.kind === 'bullet') {
        const target = projectile.target
        if (target && !target.dead) target.takeDamage(projectile.damage, projectile.source)
        this.sparks.burst(point, {
          count: 4, color: 0xffd58a, speed: 5, up: 1.5, gravity: -9, life: 0.3, size: 0.34, alpha: 0.95,
        })
        return
      }

      const splash = projectile.splash || 0
      const sourceTeam = projectile.source?.team || null
      const x = point.x
      const z = point.z
      const ground = this.terrain.sample(x, z)
      const crater = projectile.crater || 0
      const big = projectile.artillery || projectile.kind === 'bomb' || crater >= 6

      if (crater > 0) {
        this.terrain.deform(x, z, crater, 0.7 + crater * 0.14, 0.65 + crater * 0.03)
        this.stats.craters++
      }

      if (splash > 0) {
        for (const unit of this.units) {
          if (unit.dead || unit.aircraft) continue
          if (sourceTeam && unit.team === sourceTeam) continue
          const radius = entityRadius(unit)
          const distance = Math.hypot(unit.x - x, unit.z - z)
          if (distance > splash + radius) continue
          const falloff = clamp(1 - distance / (splash + radius) * 0.72, 0.24, 1)
          unit.takeDamage(projectile.damage * falloff, projectile.source)
        }
        for (const building of this.buildings) {
          if (building.dead || !building.built) continue
          if (sourceTeam && building.team === sourceTeam) continue
          const distance = Math.hypot(building.x - x, building.z - z)
          if (distance > splash + building.radius) continue
          const falloff = clamp(1 - distance / (splash + building.radius) * 0.6, 0.35, 1)
          building.takeDamage(projectile.damage * falloff, projectile.source)
        }
      } else if (projectile.target && !projectile.target.dead) {
        const target = projectile.target
        const distance = Math.hypot(target.x - x, target.z - z)
        if (distance < 5) target.takeDamage(projectile.damage, projectile.source)
      }

      this.explosion(new THREE.Vector3(x, ground + 0.5, z), big ? 7 + splash * 0.25 : 2.6 + splash * 0.22, big)
      this.sfx.explode(big)
      this.shake = Math.min(2.8, this.shake + (big ? 1.35 : 0.38))
    },

    explosion(position, radius, big = false) {
      const flash = new THREE.Mesh(
        new THREE.SphereGeometry(1, 8, 6),
        new THREE.MeshBasicMaterial({
          color: big ? 0xffb060 : 0xffd18a,
          transparent: true,
          opacity: 0.88,
          blending: THREE.AdditiveBlending,
          depthWrite: false,
        }),
      )
      flash.position.copy(position)
      flash.scale.setScalar(radius * 0.28)
      this.scene.add(flash)
      this.effects.push({
        obj: flash,
        ttl: big ? 0.62 : 0.34,
        update: (effect, dt) => {
          effect.obj.scale.multiplyScalar(1 + dt * (big ? 5.2 : 6.5))
          effect.obj.material.opacity = Math.max(0, effect.obj.material.opacity - dt * 2.3)
        },
      })
      this.particles.burst(position, {
        count: Math.round(big ? 30 : 12),
        color: 0xffb061,
        speed: radius * (big ? 1.1 : 1.5),
        spread: 0.9,
        up: radius * 0.42,
        gravity: -8,
        life: big ? 1.05 : 0.55,
        size: radius * 0.16,
        sizeVar: 0.8,
        alpha: 0.95,
      })
      this.sparks.burst(position, {
        count: Math.round(big ? 20 : 8),
        color: 0xffe7a6,
        speed: radius * 1.7,
        up: radius * 0.7,
        gravity: -17,
        life: big ? 0.8 : 0.45,
        size: 0.42,
        alpha: 1,
      })
      this.particles.smoke(new THREE.Vector3(position.x, position.y + 0.5, position.z), {
        count: Math.round(big ? 12 : 4),
        color: 0x3d3a33,
        size: big ? 3.1 : 1.5,
        life: big ? 3.4 : 1.8,
        rise: big ? 3.4 : 1.8,
        spread: radius * 0.7,
        alpha: big ? 0.5 : 0.35,
      })
    },

    muzzleFlash(muzzle, size = 0.5, targetX, targetZ) {
      const flash = createMuzzleFlash(0xffd58a)
      flash.position.copy(muzzle)
      flash.scale.setScalar(size)
      this.scene.add(flash)
      this.effects.push({
        obj: flash,
        ttl: 0.075,
        update: (effect, dt) => {
          effect.obj.scale.multiplyScalar(1 + dt * 15)
          effect.obj.material.opacity = Math.max(0, effect.obj.material.opacity - dt * 9)
        },
      })
      const dx = targetX - muzzle.x
      const dz = targetZ - muzzle.z
      const length = Math.hypot(dx, dz) || 1
      this.sparks.burst(muzzle, {
        count: 2,
        color: 0xffd58a,
        speed: 9,
        spread: 0.25,
        up: 1.4,
        gravity: -8,
        life: 0.16,
        size: 0.26,
        direction: { x: dx / length, y: 0.12, z: dz / length },
      })
    },

    smokePuff(position, scale = 1) {
      this.particles.smoke(position, {
        count: 1,
        color: scale > 0.45 ? 0x4a4740 : 0x8b8779,
        size: (scale > 0.45 ? 2.1 : 1.1) * (0.8 + Math.random() * 0.5),
        life: 0.9 + Math.random() * 0.7,
        rise: 0.8 + Math.random() * 0.8,
        spread: 0.4,
        alpha: 0.26,
      })
    },

    // ── death & wreckage ─────────────────────────────────────────────────
    destroyUnit(unit, source) {
      if (!unit || unit.dead) return
      unit.dead = true
      unit.hp = 0
      const position = unit.model.position.clone()
      if (unit.ring) unit.ring.visible = false

      this.selection = this.selection.filter(entity => entity !== unit)
      this.scene.remove(unit.model)
      if (unit.aircraft && unit.ring) {
        this.scene.remove(unit.ring)
        unit.ring.geometry?.dispose()
        unit.ring.material?.dispose()
      }

      if (source?.team === 'player' && unit.team === 'enemy') this.stats.kills++

      const category = unit.def.category
      const blastRadius = category === 'soldier' ? 2.2 : category === 'plane' ? 7 : 4.2
      const blast = new THREE.Vector3(unit.x, Math.max(unit.model.position.y, this.terrain.sample(unit.x, unit.z) + 0.5), unit.z)
      this.explosion(blast, blastRadius, category === 'plane' || category === 'tank')
      this.sfx.explode(category !== 'soldier')

      const wreck = createWreck(unit)
      const wreckY = this.terrain.sample(unit.x, unit.z) + (unit.aircraft ? 0.4 : 0.02)
      wreck.position.set(unit.x, wreckY, unit.z)
      wreck.rotation.copy(unit.model.rotation)
      if (unit.aircraft) {
        wreck.rotation.z = (Math.random() - 0.5) * 0.8
        wreck.rotation.x = 0.22
      }
      wreck.traverse(o => { if (o.isMesh) o.castShadow = true })
      this.scene.add(wreck)
      this.wrecks.push({ obj: wreck, ttl: category === 'soldier' ? 16 : 28, smoke: 0.4 })

      if (unit.team === 'player' && (category === 'tank' || category === 'plane')) {
        this.ui?.toast(`${unit.def.name.toUpperCase()} DESTROYED`, 'warn')
      }
      if (this.hoverEntity === unit) this.hoverEntity = null
      this.ui?.updateSelection()
    },

    destroyBuilding(building, source) {
      if (!building || building.dead) return
      building.dead = true
      building.hp = 0
      if (building.ring) building.ring.visible = false
      const wasHq = building.def.key === 'hq'
      const position = building.model.position.clone()
      this.selection = this.selection.filter(entity => entity !== building)
      this.scene.remove(building.model)
      building.dispose()

      const blast = new THREE.Vector3(building.x, position.y + 2.6, building.z)
      this.explosion(blast, wasHq ? 16 : Math.max(4, building.def.size * 0.55), wasHq || building.def.size >= 10)
      this.sfx.explode(true)

      const wreck = createWreck(building)
      wreck.position.copy(position)
      wreck.rotation.copy(building.model.rotation)
      this.scene.add(wreck)
      this.wrecks.push({ obj: wreck, ttl: wasHq ? 60 : 40, smoke: 0.3 })

      if (building.team === 'player') {
        this.ui?.toast(`${building.def.name.toUpperCase()} DESTROYED`, 'warn')
      } else if (wasHq) {
        this.ui?.toast('ENEMY HEADQUARTERS DESTROYED', 'good')
      }
      if (this.hoverEntity === building) this.hoverEntity = null
      this.ui?.updateSelection()
      if (wasHq) this.checkVictory()
    },
  })
}

export { _center, _pos }

import * as THREE from 'three'
import { createBuildingModel, createGroundMarker } from './models.js'
import { GAME_RULES } from './data.js'
import { HALF } from './terrain.js'
import { clamp } from './util.js'

const _point = new THREE.Vector3()

function disposeObject(obj) {
  if (!obj) return
  obj.traverse?.(child => {
    if (child.isMesh || child.isLine || child.isPoints) {
      child.geometry?.dispose()
      if (Array.isArray(child.material)) child.material.forEach(material => material.dispose())
      else child.material?.dispose()
    }
  })
  obj.parent?.remove(obj)
}

export function installActions(proto) {
  Object.assign(proto, {
    // ── spawning ─────────────────────────────────────────────────────────
    spawnUnit(def, team, x, z) {
      if (!def) return null
      const UnitClass = this.UnitClass
      if (!UnitClass) return null
      const unit = new UnitClass(this, def, team, x, z)
      this.units.push(unit)
      return unit
    },

    spawnBuilding(def, team, x, z, built = true) {
      if (!def) return null
      const BuildingClass = this.BuildingClass
      if (!BuildingClass) return null
      const building = new BuildingClass(this, def, team, x, z, built)
      this.buildings.push(building)
      return building
    },

    findSpawnSpot(x, z, radius = 2.4, team = 'player') {
      const flying = radius >= 5
      const blocked = (px, pz) => {
        if (Math.abs(px) > HALF - 12 || Math.abs(pz) > HALF - 12) return true
        if (!flying && this.map.water && this.terrain.sample(px, pz) < 0.45) return true
        if (flying) return false
        for (const building of this.buildings) {
          if (building.dead) continue
          if (Math.hypot(px - building.x, pz - building.z) < building.radius + radius + 0.8) return true
        }
        for (const unit of this.units) {
          if (unit.dead || unit.aircraft) continue
          if (Math.hypot(px - unit.x, pz - unit.z) < unit.radius + radius * 0.8 + 0.4) return true
        }
        return false
      }
      const baseRadius = Math.max(radius + 2.5, 5)
      for (let ring = 0; ring < 14; ring++) {
        const distance = baseRadius + ring * 2.6
        const steps = 10 + ring * 2
        for (let i = 0; i < steps; i++) {
          const angle = (i / steps) * Math.PI * 2 + ring * 0.63 + (team === 'enemy' ? Math.PI : 0)
          const px = clamp(x + Math.cos(angle) * distance, -HALF + 14, HALF - 14)
          const pz = clamp(z + Math.sin(angle) * distance, -HALF + 14, HALF - 14)
          if (!blocked(px, pz)) return { x: px, z: pz }
        }
      }
      return { x: clamp(x, -HALF + 14, HALF - 14), z: clamp(z, -HALF + 14, HALF - 14) }
    },

    // ── production ───────────────────────────────────────────────────────
    productionForCategory(category) {
      let best = null
      for (const building of this.buildings) {
        if (building.dead || !building.built || building.team !== 'player') continue
        if (!building.def.produces.includes(category)) continue
        if (!best || building.queue.length < best.queue.length) best = building
      }
      return best
    },

    queuedCount(unitId) {
      let count = 0
      for (const building of this.buildings) {
        if (building.dead || building.team !== 'player') continue
        for (const item of building.queue) if (item.def.id === unitId) count++
      }
      return count
    },

    queueForTeam(unit, building, team) {
      if (!unit || !building || building.dead) return false
      if (!building.built || !building.def.produces.includes(unit.category)) {
        if (team === 'player') {
          this.ui?.toast(`REQUIRES ${this.producerName(unit.category).toUpperCase()}`, 'warn')
          this.sfx.deny()
        }
        return false
      }
      if (building.queue.length >= 5) {
        if (team === 'player') this.ui?.toast('PRODUCTION QUEUE FULL', 'warn')
        return false
      }
      const bank = team === 'player' ? this.supplies : this.enemySupplies
      if (bank < unit.cost) {
        if (team === 'player') {
          this.ui?.toast('INSUFFICIENT SUPPLY', 'warn')
          this.sfx.deny()
        }
        return false
      }
      const pop = this.popFor(team)
      if (pop.used + unit.pop > pop.cap) {
        if (team === 'player') {
          this.ui?.toast('POPULATION CAP REACHED · BUILD SUPPLY DEPOTS', 'warn')
          this.sfx.deny()
        }
        return false
      }
      if (!building.queueUnit(unit)) return false
      if (team === 'player') {
        this.supplies -= unit.cost
        this.sfx.click()
      } else {
        this.enemySupplies -= unit.cost
      }
      this.recalculateEconomy()
      return true
    },

    producerName(category) {
      return category === 'soldier' ? 'Barracks' : category === 'plane' ? 'Airfield' : 'Factory'
    },

    queueUnit(unit) {
      if (!unit) return false
      const building = this.productionForCategory(unit.category)
      if (!building) {
        this.ui?.toast(`REQUIRES ${this.producerName(unit.category).toUpperCase()}`, 'warn')
        this.sfx.deny()
        return false
      }
      return this.queueForTeam(unit, building, 'player')
    },

    // ── placement ────────────────────────────────────────────────────────
    isPlacementValid(def, x, z, team = 'player') {
      if (!def) return false
      if (!this.terrain.canBuild(x, z, def.size)) return false
      if (Math.abs(x) > HALF - 14 || Math.abs(z) > HALF - 14) return false
      for (const building of this.buildings) {
        if (building.dead) continue
        const spacing = (def.size + building.def.size) * 0.55 + 1.4
        if (Math.hypot(x - building.x, z - building.z) < spacing) return false
      }
      for (const capture of this.capturePoints) {
        if (Math.hypot(x - capture.x, z - capture.z) < GAME_RULES.captureRadius * 0.55 + def.size * 0.35) return false
      }
      return true
    },

    beginPlacement(key) {
      if (this.gameOver) return
      const def = this.buildingsByKey[key]
      if (!def) return
      if (this.supplies < def.cost) {
        this.ui?.toast('INSUFFICIENT SUPPLY', 'warn')
        this.sfx.deny()
        return
      }
      this.cancelModes()
      this.mode = 'placement'
      this.placement = { def, x: 0, z: 0, valid: false }
      const ghost = createBuildingModel(def, this.playerFaction)
      ghost.traverse(child => {
        if (!child.isMesh) return
        child.material = Array.isArray(child.material)
          ? child.material.map(material => material.clone())
          : child.material.clone()
        const materials = Array.isArray(child.material) ? child.material : [child.material]
        materials.forEach(material => {
          material.transparent = true
          material.opacity = 0.46
          material.depthWrite = false
        })
        child.castShadow = false
        child.receiveShadow = false
      })
      ghost.visible = false
      this.scene.add(ghost)
      this.ghost = ghost
      const ring = createGroundMarker(def.size * 0.62, 0x7ad9c5)
      ring.visible = false
      this.scene.add(ring)
      this.ghostRing = ring
      this.renderer.domElement.classList.add('placing')
      this.ui?.setPlacement(`PLACE ${def.name.toUpperCase()} · ${def.cost} SUPPLY`, true)
      this.ui?.setLock(null)
      this.updateGhostVisual()
    },

    updateGhostVisual() {
      if (this.artilleryPreview && this.mode === 'artillery') this.updateArtilleryPreview()
      if (!this.ghost || this.mode !== 'placement' || !this.placement) return
      const point = this.terrainPoint()
      if (!point) {
        this.ghost.visible = false
        if (this.ghostRing) this.ghostRing.visible = false
        return
      }
      const { def } = this.placement
      const valid = this.isPlacementValid(def, point.x, point.z, 'player')
      this.placement.x = point.x
      this.placement.z = point.z
      this.placement.valid = valid
      const y = this.terrain.sample(point.x, point.z)
      this.ghost.visible = true
      this.ghost.position.set(point.x, y, point.z)
      this.ghost.rotation.y = Math.atan2(-point.x, -point.z)
      if (this.ghostRing) {
        this.ghostRing.visible = true
        this.ghostRing.position.set(point.x, y + 0.18, point.z)
        this.ghostRing.material.color.setHex(valid ? 0x7ad9c5 : 0xe0705a)
        this.ghostRing.material.opacity = 0.55 + Math.sin(this.elapsed * 4) * 0.18
      }
      this.ui?.setPlacement(
        valid
          ? `PLACE ${def.name.toUpperCase()} · ${def.cost} SUPPLY`
          : 'INVALID SITE · MOVE TO FLAT GROUND',
        valid,
      )
    },

    placeBuilding() {
      if (!this.placement) return false
      const { def, valid, x, z } = this.placement
      if (!valid) {
        this.ui?.toast('INVALID BUILD SITE', 'warn')
        this.sfx.deny()
        return false
      }
      if (this.supplies < def.cost) {
        this.ui?.toast('INSUFFICIENT SUPPLY', 'warn')
        this.sfx.deny()
        this.cancelModes()
        return false
      }
      this.supplies -= def.cost
      this.recalculateEconomy()
      this.spawnBuilding(def, 'player', x, z, false)
      this.ui?.toast(`${def.name.toUpperCase()} UNDER CONSTRUCTION`, 'good')
      this.sfx.build()
      this.cancelModes()
      return true
    },

    cancelPlacement() {
      this.cancelModes()
    },

    cancelModes() {
      this.mode = null
      this.placement = null
      this.rallyBuilding = null
      this.targetingArtillery = false
      if (this.ghost) {
        disposeObject(this.ghost)
        this.ghost = null
      }
      if (this.ghostRing) {
        disposeObject(this.ghostRing)
        this.ghostRing = null
      }
      if (this.artilleryPreview) {
        disposeObject(this.artilleryPreview.group)
        this.artilleryPreview = null
      }
      this.renderer?.domElement?.classList.remove('placing')
      this.ui?.setPlacement(null)
    },

    updateArtilleryPreview() {
      if (!this.artilleryPreview) return
      const point = this.terrainPoint()
      if (!point) {
        this.artilleryPreview.group.visible = false
        return
      }
      this.artilleryPreview.group.visible = true
      this.artilleryPreview.group.position.set(point.x, this.terrain.sample(point.x, point.z) + 0.16, point.z)
      const preview = this.artilleryPreview
      preview.ring.material.opacity = 0.55 + Math.sin(this.elapsed * 4.5) * 0.2
      preview.disc.material.opacity = 0.06 + (Math.sin(this.elapsed * 3.2) * 0.5 + 0.5) * 0.04
    },

    // ── orders & abilities ───────────────────────────────────────────────
    beginRally() {
      const buildings = this.selection.filter(entity => entity.kind === 'building' && entity.team === 'player' && entity.built)
      if (!buildings.length) {
        this.ui?.toast('SELECT A PRODUCTION STRUCTURE', 'warn')
        this.sfx.deny()
        return
      }
      this.cancelModes()
      this.mode = 'rally'
      this.rallyBuilding = buildings[0]
      this.ui?.setPlacement('RALLY POINT · CLICK DESTINATION')
      this.renderer.domElement.classList.add('placing')
    },

    setRally(x, z) {
      const building = this.rallyBuilding
      if (!building || building.dead) return
      building.rally.set(clamp(x, -HALF + 12, HALF - 12), 0, clamp(z, -HALF + 12, HALF - 12))
      this.orderMarker(x, z, '#d3b77b')
      this.ui?.toast(`RALLY POINT SET · ${building.def.name.toUpperCase()}`)
      this.sfx.order()
    },

    beginAttackMove() {
      if (!this.selectedPlayerUnits.length) {
        this.ui?.toast('SELECT UNITS FIRST', 'warn')
        this.sfx.deny()
        return
      }
      this.cancelModes()
      this.mode = 'attackMove'
      this.ui?.setPlacement('ATTACK-MOVE · CLICK TARGET GROUND')
      this.renderer.domElement.classList.add('placing')
    },

    beginArtillery() {
      if (this.gameOver) return
      if (this.artilleryCooldown > 0) {
        this.ui?.toast(`BARRAGE RECHARGING · ${Math.ceil(this.artilleryCooldown)}s`, 'warn')
        this.sfx.deny()
        return
      }
      if (this.mode === 'artillery') {
        this.cancelModes()
        return
      }
      this.cancelModes()
      this.mode = 'artillery'
      this.targetingArtillery = true
      const group = new THREE.Group()
      const ring = createGroundMarker(GAME_RULES.artilleryRadius, 0xe0705a)
      ring.material.opacity = 0.65
      group.add(ring)
      const disc = new THREE.Mesh(
        new THREE.CircleGeometry(GAME_RULES.artilleryRadius, 40),
        new THREE.MeshBasicMaterial({ color: 0xe0705a, transparent: true, opacity: 0.075, depthWrite: false, side: THREE.DoubleSide }),
      )
      disc.rotation.x = -Math.PI / 2
      disc.position.y = 0.05
      disc.raycast = () => {}
      group.add(disc)
      group.visible = false
      this.scene.add(group)
      this.artilleryPreview = { group, ring, disc }
      this.renderer.domElement.classList.add('placing')
      this.ui?.setPlacement('BARRAGE · CLICK TARGET AREA')
      this.updateArtilleryPreview()
    },

    callArtillery(x, z) {
      if (this.artilleryCooldown > 0) return false
      const tx = clamp(x, -HALF + 12, HALF - 12)
      const tz = clamp(z, -HALF + 12, HALF - 12)
      this.artilleryCooldown = GAME_RULES.artilleryCooldown
      const source = { team: 'player', dead: false, def: { damage: 180 } }
      const shells = GAME_RULES.artilleryShells
      for (let i = 0; i < shells; i++) {
        const angle = Math.random() * Math.PI * 2
        const distance = Math.sqrt(Math.random()) * GAME_RULES.artilleryRadius * 0.82
        this.strikes.push({
          t: 0.45 + i * 0.34 + Math.random() * 0.22,
          x: tx + Math.cos(angle) * distance,
          z: tz + Math.sin(angle) * distance,
          damage: 165 + Math.random() * 70,
          splash: 14,
          crater: 7.2 + Math.random() * 2.4,
          source,
        })
      }
      this.orderMarker(tx, tz, '#e0705a', GAME_RULES.artilleryRadius * 0.55)
      this.sfx.artillery()
      this.ui?.toast('BARRAGE INBOUND · DANGER CLOSE', 'warn')
      this.shake = Math.min(2.2, this.shake + 0.5)
      this.targetingArtillery = false
      this.cancelModes()
      return true
    },

    orderMarker(x, z, color = '#7ad9c5', radius = 2.1) {
      const marker = createGroundMarker(radius, new THREE.Color(color).getHex())
      marker.position.set(x, this.terrain.sample(x, z) + 0.22, z)
      this.scene.add(marker)
      this.effects.push({
        obj: marker,
        ttl: 0.85,
        update: (effect, dt) => {
          effect.obj.scale.multiplyScalar(1 + dt * 1.6)
          effect.obj.material.opacity = Math.max(0, effect.obj.material.opacity - dt * 1.4)
        },
      })
      this.lastMoveMark = this.elapsed
    },

    stopSelected() {
      const units = this.selectedPlayerUnits
      if (!units.length) return
      for (const unit of units) unit.stop()
    },

    holdSelected() {
      const units = this.selectedPlayerUnits
      if (!units.length) return
      for (const unit of units) unit.hold()
    },

    returnToBase() {
      const units = this.selectedPlayerUnits
      if (!units.length) return
      for (const unit of units) unit.returnToBase()
      this.sfx.order()
    },

    orderRepair() {
      const engineers = this.selectedPlayerUnits.filter(unit => unit.def.repair)
      if (!engineers.length) {
        this.ui?.toast('SELECT AN ENGINEER', 'warn')
        this.sfx.deny()
        return
      }
      let ordered = false
      for (const engineer of engineers) {
        let best = null
        let bestDistance = 90
        for (const target of [...this.playerUnits, ...this.playerBuildings]) {
          if (target === engineer || target.dead) continue
          if (target.hp >= target.maxHp - 1) continue
          if (target.kind === 'unit' && target.aircraft) continue
          const distance = Math.hypot(target.x - engineer.x, target.z - engineer.z)
          if (distance < bestDistance) {
            best = target
            bestDistance = distance
          }
        }
        if (best) {
          engineer.repair(best)
          ordered = true
        }
      }
      if (!ordered) {
        this.ui?.toast('NO DAMAGED STRUCTURE OR VEHICLE IN RANGE', 'warn')
        this.sfx.deny()
      } else {
        this.sfx.order()
      }
    },

    // ── camera & app ─────────────────────────────────────────────────────
    setCameraTarget(x, z) {
      const tx = clamp(x, -HALF + 18, HALF - 18)
      const tz = clamp(z, -HALF + 18, HALF - 18)
      this.cameraGoal.set(tx, this.terrain.sample(tx, tz) + 2, tz)
    },

    focusBase() {
      this.setCameraTarget(this.playerBase.x, this.playerBase.z)
    },

    focusEnemy() {
      this.setCameraTarget(this.enemyBase.x, this.enemyBase.z)
    },

    focusSelection() {
      const targets = this.selection.filter(entity => !entity.dead)
      if (!targets.length) {
        this.focusBase()
        return
      }
      let x = 0, z = 0
      for (const entity of targets) {
        x += entity.x
        z += entity.z
      }
      this.setCameraTarget(x / targets.length, z / targets.length)
    },

    selectAllArmy() {
      this.clearSelection()
      for (const unit of this.playerUnits) {
        if (unit.dead) continue
        unit.setSelected(true)
        this.selection.push(unit)
      }
      this.ui?.updateSelection()
      if (this.selection.length) this.sfx.select()
    },

    requestMenu() {
      this.app?.returnToMenu?.()
    },

    restart() {
      this.app?.restartGame?.(this.options)
    },
  })
}

