  if (!UnitClass) return null
  const unit = new UnitClass(this, def, team, x, z)
  this.units.push(unit)
  return unit
},

spawnBuilding(def, team, x, z, built = true) {
  if (!def) return null
  const BuildingClass = this.BuildingClass
  if (!BuildingClass) return null
  const building = new BuildingClass(this, def, team, x, z, built)
  this.buildings.push(building)
  return building
},

